// users.gateway.js - one module per table
const INSERT = 'INSERT INTO users(id, name) VALUES($1, $2) RETURNING id';

export function usersGateway(pool) {
  return {
    insert: (u) => pool.query(INSERT, [u.id, u.name]).then(r => r.rows[0]),
    find: (id) =>
      pool.query('SELECT id, name FROM users WHERE id = $1', [id])
          .then(r => r.rows[0]),
  };
}
